// --- TAMIS : Déduplication + Score (articles en ANGLAIS) ---

const SEUIL_SCORE = 3;
const MAX_ITEMS = 15;

const CRITICAL_KEYWORDS = [
  "cybersecurity", "cybercrime", "shadow ai", "sovereign ai",
  "pentest", "penetration test", "security audit", "cyber audit",
  "data leak", "ransomware", "ransom", "phishing", "attack",
  "vulnerability", "threat", "offensive security", "red team",
  "critical infrastructure", "personal data", "gdpr",
  "compliance", "digital sovereignty", "africa", "cameroon"
];

const SECONDARY_KEYWORDS = [
  "cloud", "security", "infosec", "it", "digital", "transformation",
  "enterprise", "risk", "governance", "protection", "authentication",
  "artificial intelligence", "ai", "llm", "api", "machine learning",
  "devsecops"
];

const LOCAL_TERMS = {
  africa: 3, afrique: 3, cameroon: 5, cameroun: 5
};

function computeScore(item) {
  const text = `${item.title || ''} ${item.description || ''} ${item.content || ''}`.toLowerCase();
  let score = 0;
  for (const kw of CRITICAL_KEYWORDS) { if (text.includes(kw)) score += 3; }
  for (const kw of SECONDARY_KEYWORDS) { if (text.includes(kw)) score += 1; }
  for (const [term, bonus] of Object.entries(LOCAL_TERMS)) {
    if (text.includes(term)) { score += bonus; break; }
  }
  return score;
}

const seenUrls = new Set();
const scoredItems = [];

for (const item of $input.all()) {
  const url = item.json.url || item.json.link;
  if (!url || seenUrls.has(url)) continue;
  seenUrls.add(url);
  const score = computeScore(item.json);
  if (score < SEUIL_SCORE) continue;
  scoredItems.push({ item, score });
}

scoredItems.sort((a, b) => b.score - a.score);
return scoredItems.slice(0, MAX_ITEMS).map(entry => entry.item);

// 1. Récupérer la liste fusionnée envoyée par le nœud Merge
const mergedItems = $input.all();

const articles = [];
const publishedRows = [];

// 2. Trier dynamiquement les éléments selon leur provenance
for (const item of mergedItems) {
  // Les lignes de la base de données possèdent la clé 'est_publie'
  if (item.json.hasOwnProperty('est_publie')) {
    publishedRows.push(item);
  } else {
    articles.push(item);
  }
}

// 3. Extraire les URLs et titres déjà publiés
const publishedUrls = new Set();
const publishedTitles = new Set();

for (const row of publishedRows) {
  if (row.json.url) {
    publishedUrls.add(row.json.url.trim());
  }
  if (row.json.titre) {
    publishedTitles.add(row.json.titre.trim().toLowerCase());
  }
}

// 4. Filtrer les articles du flux RSS
const filteredArticles = articles.filter(article => {
  const url = (article.json.url || article.json.link || '').trim();
  const title = (article.json.title || '').trim().toLowerCase();

  return !publishedUrls.has(url) && !publishedTitles.has(title);
});

return filteredArticles;

const items = $input.all();
const groupedArticles = [];

for (const item of items) {
  groupedArticles.push({
    titre: item.json.title || 'Sans titre',
    url: item.json.url || item.json.link,
    description: item.json.content || 'Pas de description'
  });
}

return {
  articles: groupedArticles,
  total: groupedArticles.length,
  date_traitement: new Date().toISOString()
};

