const html = $json.solution.response;

function getText(html, startMarker, endMarker) {
  const start = html.indexOf(startMarker);
  if (start === -1) return '';
  const end = html.indexOf(endMarker, start);
  if (end === -1) return '';
  return html.substring(start + startMarker.length, end).trim();
}

function getMetaContent(html, name) {
  const regex = new RegExp(`<meta name="${name}" content="([^"]+)"`, 'i');
  const match = html.match(regex);
  return match ? match[1] : '';
}

let title = getText(html, '<h1 class="story-title">', '</h1>');
title = title.replace(/<a[^>]*>([^<]*)<\/a>/, '$1').trim();

const description = getMetaContent(html, 'description');

let content = getText(html, '<div class="articlebody clear cf" id="articlebody">', '<div class="stophere" id="hiddenH1"></div>');
content = content
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{
