  }
}];

// 1. Récupérer les données validées depuis le nœud Wait 2
const waitNode = $('Wait: Checkpoint 2 (Approve Post & Slides)').first().json;

// ✅ CORRECTIF : n8n encapsule les données du webhook de reprise dans la clé "body"
const data = waitNode.body || waitNode;

let postText = data.post_final;
const slides = data.carousel_final;

if (!slides || !Array.isArray(slides)) {
  // Log de secours pour inspecter la structure réelle dans l'onglet Output de n8n
  console.log("=== Structure de waitNode détectée ===", JSON.stringify(waitNode, null, 2));
  throw new Error("Le carrousel validé est introuvable dans le payload.");
}

// --- NETTOYAGE DU TEXTE POUR LINKEDIN ---
if (postText) {
  postText = postText.replace(/\*\*/g, ''); // Enlève le gras Markdown
  postText = postText.replace(/\*/g, '');   // Enlève l'italique
  postText = postText.replace(/###/g, '');  // Enlève les titres H3
  postText = postText.trim();
}

// 2. Récupérer le logo binaire du nœud "Download Logo"
const logoBuffer = await this.helpers.getBinaryDataBuffer(0, 'data', 'Download Logo');
const logoBase64 = `data:image/png;base64,${logoBuffer.toString('base64')}`;

// 3. Génération des slides
let slidesHTML = '';
for (let i = 0; i < slides.length; i++) {
  const originalContent = slides[i].slide_content || "";
  let cleanContent = originalContent.replace(/\[Nom de votre entreprise\]/g, 'OffensiveSkills');
  cleanContent = cleanContent.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

  const originalTitle = slides[i].slide_title || "";
  const cleanTitle = originalTitle.replace(/^#+\s*/, '');

  slidesHTML += `
    <div class="slide">
      <div class="top-bar"></div>
      <div class="number">0${i + 1}</div>
      <img class="logo-bg" src="${logoBase64}">

      <div class="container">
        <div class="title">${cleanTitle}</div>
        <div class="divider"></div>
        <div class="content">${cleanContent}</div>
      </div>

      <div class="footer">
        <img class="logo-small" src="${logoBase64}">
        <span>OffensiveSkills — Expertise Cyber & IA</span>
      </div>
    </div>
  `;
}

// 4. Template HTML avec CSS Avancé (1080x1080)
const html = `
<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="UTF-8">
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;700;800&display=swap');
        @page { size: 1080px 1080px; margin: 0; }\n        body { margin: 0; padding: 0; font-family: 'Inter', sans-serif; background-color: #050505; }\n        .slide { width: 1080px; height: 1080px; page-break-after: always; position: relative; overflow: hidden; background: radial-gradient(circle at 50% 50%, #1a1a2e 0%, #050505 100%); display: flex; flex-direction: column; justify-content: center; align-items: center; }\n        .top-bar { position: absolute; top: 0; left: 0; width: 100%; height: 12px; background: linear-gradient(90deg, #9d4edd, #3a86ff, #ff006e); }\n        .container { width: 80%; z-index: 2; text-align: left; }\n        .title { font-size: 48px; font-weight: 800; line-height: 1.1; color: #3a86ff; margin-bottom: 30px; text-transform: uppercase; letter-spacing: -2px; }\n        .divider { width: 100px; height: 8px; background: #3a86ff; margin-bottom: 40px; border-radius: 4px; }\n        .content { font-size: 38px; line-height: 1.5; color: #cbd5e1; font-weight: 400; }\n        strong { color: #3a86ff; font-weight: 800; }\n        .logo-bg { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 900px; opacity: 0.05; z-index: 1; filter: grayscale(1); }\n        .footer { position: absolute; bottom: 50px; left: 0; width: 100%; display: flex; align-items: center; padding: 0 60px; box-sizing: border-box; color: #64748b; font-size: 22px; }\n        .logo-small { height: 50px; margin-right: 20px; }\n        .number { position: absolute; top: 60px; right: 60px; font-size: 40px; font-weight: 800; color: #3a86ff; opacity: 0.8; }\n    </style>\n</head>\n<body>\n    ${slidesHTML}\n</body>\n</html>\n`;

return [{
